using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Windows.Forms;
namespace VinsPDF {
internal static class PdfTools {
 internal static string Quote(string value){var b=new StringBuilder("\"");int slashes=0;foreach(char c in value){if(c=='\\'){slashes++;continue;}if(c=='\"'){b.Append('\\',slashes*2+1);b.Append(c);}else{b.Append('\\',slashes);b.Append(c);}slashes=0;}b.Append('\\',slashes*2);return b.Append('"').ToString();}
 public static void Run(params string[] args){string exe=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"qpdf","qpdf.exe");if(!File.Exists(exe))throw new IOException("The PDF tools component is missing. Reinstall VinsPDF.");var info=new ProcessStartInfo(exe,string.Join(" ",args.Select(Quote))){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,RedirectStandardOutput=true,RedirectStandardError=true};bool held=Monitor.IsEntered(PdfEngine.NativeGate);if(held)Monitor.Exit(PdfEngine.NativeGate);try{using(var process=new Process{StartInfo=info}){process.Start();var output=process.StandardOutput.ReadToEndAsync();var errors=process.StandardError.ReadToEndAsync();if(!process.WaitForExit(300000)){process.Kill();throw new IOException("This PDF operation took too long. The open document has not been replaced.");}string error=errors.Result;string ignored=output.Result;if(process.ExitCode!=0&&process.ExitCode!=3)throw new IOException("Could not process this PDF. "+error);}}finally{if(held)Monitor.Enter(PdfEngine.NativeGate);}}
 public static void InstallFile(string source,string target){string temp=Path.GetFullPath(target)+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.Copy(source,temp,false);if(File.Exists(target))File.Replace(temp,target,null);else File.Move(temp,target);}finally{if(File.Exists(temp))File.Delete(temp);}}
}
internal sealed partial class PdfEngine {
 readonly List<string> scratchFiles=new List<string>();string scratchFolder;public string ExportReport;
 string Scratch(){if(scratchFolder==null){scratchFolder=Path.Combine(Path.GetTempPath(),"VinsPDF",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(scratchFolder);}string file=Path.Combine(scratchFolder,Guid.NewGuid().ToString("N")+".pdf");scratchFiles.Add(file);return file;}
 void ReleaseScratch(string file){try{if(File.Exists(file))File.Delete(file);scratchFiles.Remove(file);}catch(IOException){} }
 void CleanupScratch(){foreach(string file in scratchFiles.ToArray())ReleaseScratch(file);if(scratchFolder!=null)try{Directory.Delete(scratchFolder,false);}catch(IOException){} }
 public void ExportEditableReduced(string target,int[] order,int quality,bool thorough=false){string source=Scratch(),selected=null,candidate=Scratch();try{ExportCopy(source);if(!order.SequenceEqual(Enumerable.Range(0,Count))){selected=Scratch();PdfTools.Run(source,"--pages",".",string.Join(",",order.Select(i=>(i+1).ToString())),"--",selected);}string input=selected??source;if(thorough)PdfTools.Run(input,"--object-streams=generate","--compress-streams=y","--recompress-flate","--compression-level=6",candidate);else PdfTools.Run(input,"--object-streams=generate","--stream-data=preserve",candidate);using(var check=new PdfEngine()){check.Open(candidate);Check(check.Count==order.Length,"Export page count did not match.");}long before=new FileInfo(input).Length,after=new FileInfo(candidate).Length;bool smaller=after<before;PdfTools.InstallFile(smaller?candidate:input,target);ExportReport=smaller?"Saved · "+((before-after)*100.0/before).ToString("0.00")+"% smaller · editable text retained":"Saved · already optimised; editable text retained";}finally{ReleaseScratch(source);if(selected!=null)ReleaseScratch(selected);ReleaseScratch(candidate);}}
 public void ExportOrganised(string target,int[] order,int[] turns){if(order.Length==0||order.Any(i=>i<0||i>=Count))throw new IOException("Keep at least one valid page.");string source=Scratch(),result=Scratch();try{ExportCopy(source);var args=new List<string>{source,"--pages",".",string.Join(",",order.Select(i=>(i+1).ToString())),"--"};for(int i=0;i<order.Length;i++)if(turns!=null&&turns[i]%4!=0)args.Add("--rotate=+"+((turns[i]+4)%4*90)+":"+(i+1));args.Add(result);PdfTools.Run(args.ToArray());using(var check=new PdfEngine()){check.Open(result);Check(check.Count==order.Length,"Organised page count did not match.");}PdfTools.InstallFile(result,target);}finally{ReleaseScratch(source);ReleaseScratch(result);}}
 public void OrganiseInMemory(int[] order,int[] turns){string result=Scratch(),recovery=Scratch();try{ExportCopy(recovery);ExportOrganised(result,order,turns);try{Open(result);}catch{Open(recovery);throw;}foreach(string file in scratchFiles.ToArray())if(file!=result)ReleaseScratch(file);}catch{ReleaseScratch(result);throw;}}
}
internal sealed partial class MainForm {
 bool structurePending;
 void ApplyOrganisedPages(PageChoice[] choices){if(editBusy)return;editBusy=true;viewVersion++;debounce.Stop();worker.ClearIdle();UpdateEditorTools();status.Text="Applying page order…";int token=generation,oldIndex=pageIndex;int[] order=choices.Select(p=>p.Index).ToArray(),turns=choices.Select(p=>p.Rotation).ToArray();worker.Command(delegate(PdfEngine engine){try{engine.OrganiseInMemory(order,turns);var newSizes=(SizeF[])engine.Sizes.Clone();var labels=engine.PageLabels();Post(delegate{if(token!=generation)return;ClearUndoViews();searchEpoch++;searchHits.Clear();activeHit=-1;canvas.ClearObjects();ClearImages();uiHiddenLayers.Clear();uiLockedLayers.Clear();sizes=newSizes;pageLabels=labels;rotations=new int[sizes.Length];editorState=new EditState();pages.BeginUpdate();selecting=true;pages.Items.Clear();for(int i=0;i<sizes.Length;i++)pages.Items.Add("Page "+PageLabel(i));selecting=false;pages.EndUpdate();pageTotal.Text="/ "+sizes.Length;dirty=true;structurePending=true;savedOnce=true;editBusy=false;UpdateDocumentTitle();UpdateEditorTools();Navigate(Math.Max(0,Array.IndexOf(order,oldIndex)));status.Text="Pages rearranged · Save writes to the original PDF";},null);}catch(Exception ex){string message=ex.Message;Post(delegate{editBusy=false;UpdateEditorTools();DarkMessage.Show(TopLevelControl as Form??this,message,"Could not organise pages");},null);}});}
}
}
